@startuml

class University {
  + TotalEmployees : int
}

class Faculty {
  + Name : string
}

class Institute {
  + Name : string
  + Address : string
}

class Employee {
  + SocialSecurityNumber : string
  + Name : string
  + EmailAddress : string
}

class ResearchStaff extends Employee {
  + ResearchField : string
}

class AdministrativeStaff extends Employee {}

class ResearchAssistant extends ResearchStaff {
  + FieldOfResearch : string
}

class Lecturer extends ResearchAssistant {
}

class Project {
  + Name : string
  + StartDate : date
  + EndDate : date
  + Hours : int
}

class Course {
  + ID : int
  + Name : string
  + WeeklyDuration : int
}

University "1" -- "*" Faculty
University "1" -- "*" Employee
Faculty "1" -- "*" Institute
Faculty "1" -- "0..1" Employee : Dean
ResearchAssistant "*" -- "1..*" Institute
ResearchAssistant "1" -- "*" Project : involved in
Lecturer "1" -- "*" Course : teaches

@enduml

